-- 第二轮 SG 内容完善：补充覆盖法律、风险管理、网络、开发安全、运维和管理的自编练习与情景。
-- 所有题目均标记 generated/authored，不冒充官方真题。
INSERT OR IGNORE INTO questions
(id,track_id,topic,difficulty,question_type,prompt,options_json,answer_json,explanation,source_type,source_reference,language)
VALUES
('sg-practice-0026','exam-sg','リスクマネジメント','intermediate','single_choice','リスクの「移転」に該当する対応はどれか。','[{"id":"a","text":"危険なサービスの利用を中止する"},{"id":"b","text":"多要素認証を導入して発生可能性を下げる"},{"id":"c","text":"保険契約などにより損失の負担を第三者と分担する"},{"id":"d","text":"リスクを把握したうえで対策せず受容する"}]','"c"','正解は C。リスク移転は保険や契約などで損失負担を第三者へ移すこと。A は回避、B は低減、D は受容。','generated','知学 SG 自编练习 v3','ja'),
('sg-practice-0027','exam-sg','情報セキュリティの三要素','standard','single_choice','許可されていない人に顧客情報を見られないようにする性質はどれか。','[{"id":"a","text":"可用性"},{"id":"b","text":"機密性"},{"id":"c","text":"完全性"},{"id":"d","text":"保守性"}]','"b"','正解は B。機密性は認められた人だけが情報へアクセスできる性質。完全性は正確さ・完全さ、可用性は必要なとき利用できる性質。','generated','知学 SG 自编练习 v3','ja'),
('sg-practice-0028','exam-sg','認証と認可','standard','single_choice','ログイン後、一般社員には許可されていない管理画面への操作を拒否する処理はどれか。','[{"id":"a","text":"識別"},{"id":"b","text":"認証"},{"id":"c","text":"認可"},{"id":"d","text":"暗号化"}]','"c"','正解は C。認証は本人確認、認可は認証された主体に何を許可するか決めること。ログインできても全操作が許可されるわけではない。','generated','知学 SG 自编练习 v3','ja'),
('sg-practice-0029','exam-sg','暗号技術','intermediate','single_choice','ハッシュ関数の利用方法として最も適切なものはどれか。','[{"id":"a","text":"元データを必ず元に戻せるようにする"},{"id":"b","text":"入力から固定長の要約値を計算し、完全性確認などに利用する"},{"id":"c","text":"通信相手の権限を自動決定する"},{"id":"d","text":"データの可用性を保証する"}]','"b"','正解は B。暗号学的ハッシュは入力から固定長の値を計算する一方向性の関数。通常、ハッシュ値から元データを復号することはできない。','generated','知学 SG 自编练习 v3','ja'),
('sg-practice-0030','exam-sg','ネットワークセキュリティ','standard','single_choice','ファイアウォールの主な役割はどれか。','[{"id":"a","text":"通信ルールに基づきネットワーク通信を許可または遮断する"},{"id":"b","text":"データベースの正規化を行う"},{"id":"c","text":"利用者の日本語能力を判定する"},{"id":"d","text":"バックアップデータを必ず復号する"}]','"a"','正解は A。ファイアウォールはルールに基づいて通信を制御する。すべての攻撃を単独で防げるわけではなく、他の対策と組み合わせる。','generated','知学 SG 自编练习 v3','ja'),
('sg-practice-0031','exam-sg','インシデント対応','intermediate','single_choice','マルウェア感染が疑われる端末を発見した直後の対応として最も適切なものはどれか。','[{"id":"a","text":"証拠を残さず端末を初期化する"},{"id":"b","text":"組織の手順に従い影響拡大を防ぎ、担当者へ報告して記録を保全する"},{"id":"c","text":"端末を使い続けて様子を見る"},{"id":"d","text":"感染ファイルを同僚へ送って確認してもらう"}]','"b"','正解は B。手順に従って隔離などの封じ込めを行い、速やかに報告して証拠を保全する。独断の初期化は調査を妨げる可能性がある。','generated','知学 SG 自编练习 v3','ja'),
('sg-practice-0032','exam-sg','システム監査','intermediate','single_choice','システム監査人の独立性を確保するために重要なことはどれか。','[{"id":"a","text":"監査対象のシステムを自分で開発し、そのまま自己評価する"},{"id":"b","text":"監査対象部門から不当な指示を受けない立場と手続を確保する"},{"id":"c","text":"監査結果を必ず公開しない"},{"id":"d","text":"証拠を確認せず担当者の説明だけで結論を出す"}]','"b"','正解は B。監査人は客観的に評価できる独立性を確保し、十分かつ適切な証拠に基づいて結論を出す。','generated','知学 SG 自编练习 v3','ja'),
('sg-practice-0033','exam-sg','変更管理','standard','single_choice','本番システムの設定変更を行う前に実施すべきこととして最も適切なものはどれか。','[{"id":"a","text":"変更内容と影響を評価し、必要な承認、検証、切戻し計画を準備する"},{"id":"b","text":"変更履歴を残さない"},{"id":"c","text":"障害が起きてから初めて影響を調べる"},{"id":"d","text":"全利用者へ管理者権限を付与する"}]','"a"','正解は A。変更管理では影響評価、承認、テスト、実施記録、切戻し計画を準備し、障害リスクを抑える。','generated','知学 SG 自编练习 v3','ja'),
('sg-practice-0034','exam-sg','個人情報保護','standard','single_choice','個人情報を利用する際の基本的な考え方として最も適切なものはどれか。','[{"id":"a","text":"取得した情報は目的に関係なく自由に利用できる"},{"id":"b","text":"利用目的や適用法令を確認し、必要な範囲で適切に取り扱う"},{"id":"c","text":"個人情報を全社員に共有する"},{"id":"d","text":"保存期間を決めず無期限に保持する"}]','"b"','正解は B。利用目的、適用法令、アクセス権、保存期間などを踏まえて適切に取り扱う。必要以上の収集や目的外利用は避ける。','generated','知学 SG 自编练习 v3','ja'),
('sg-practice-0035','exam-sg','データベース','standard','single_choice','データベースのトランザクションにおける原子性の説明はどれか。','[{"id":"a","text":"処理の一部だけが成功してもそのまま確定する"},{"id":"b","text":"一連の処理をすべて実行するか、全体を取り消す"},{"id":"c","text":"データを必ず暗号化する"},{"id":"d","text":"複数の利用者に同じ権限を与える"}]','"b"','正解は B。原子性はトランザクションを不可分な単位として扱う性質。途中で失敗した場合に部分的な更新だけが残らないようにする。','generated','知学 SG 自编练习 v3','ja'),
('sg-practice-0036','exam-sg','Webアプリケーションセキュリティ','intermediate','single_choice','XSS のリスクを低減する対策として最も適切なものはどれか。','[{"id":"a","text":"利用者入力をすべて実行可能なHTMLとして挿入する"},{"id":"b","text":"出力先の文脈に応じたエンコードを行い、安全なDOM操作を使う"},{"id":"c","text":"すべての入力検証を無効にする"},{"id":"d","text":"HTTPSだけを有効にして他の対策をしない"}]','"b"','正解は B。XSS対策では出力文脈に応じたエンコードや安全なDOM操作が重要。HTTPSは通信を保護するが、XSS自体を防ぐものではない。','generated','知学 SG 自编练习 v3','ja'),
('sg-practice-0037','exam-sg','可用性と事業継続','intermediate','single_choice','RTO と RPO の組合せとして正しいものはどれか。','[{"id":"a","text":"RTOは目標復旧時間、RPOは目標復旧時点"},{"id":"b","text":"RTOはパスワード長、RPOは暗号鍵長"},{"id":"c","text":"RTOはログ保存期間、RPOは通信速度"},{"id":"d","text":"RTOとRPOは同じ意味である"}]','"a"','正解は A。RTOはサービスをどれくらいの時間で復旧するか、RPOはどの時点までのデータを復元する必要があるかを表す。','generated','知学 SG 自编练习 v3','ja'),
('sg-practice-0038','exam-sg','委託先管理','intermediate','single_choice','機密データを扱う業務を外部委託する際の管理として最も適切なものはどれか。','[{"id":"a","text":"委託先の管理体制や契約上の責任を確認し、必要な範囲で監督する"},{"id":"b","text":"委託後は一切確認しない"},{"id":"c","text":"全システムの管理者パスワードを渡す"},{"id":"d","text":"再委託先の有無を確認しない"}]','"a"','正解は A。委託先の安全管理措置、取扱範囲、契約、再委託、事故報告、監督方法を確認する。委託しても管理責任が消えるわけではない。','generated','知学 SG 自编练习 v3','ja'),
('sg-practice-0039','exam-sg','認証と多要素認証','intermediate','single_choice','多要素認証に該当するものはどれか。','[{"id":"a","text":"パスワードと別のパスワード"},{"id":"b","text":"パスワードと、所持する認証器が生成するコード"},{"id":"c","text":"ユーザーIDとメールアドレス"},{"id":"d","text":"秘密の質問とパスワード"}]','"b"','正解は B。多要素認証は知識・所持・生体など異なる種類の要素を組み合わせる。秘密の質問とパスワードはどちらも知識要素になり得る。','generated','知学 SG 自编练习 v3','ja'),
('sg-practice-0040','exam-sg','バックアップ','standard','single_choice','バックアップ運用の有効性を確認する方法として最も適切なものはどれか。','[{"id":"a","text":"バックアップ成功の通知だけで復旧可能と判断する"},{"id":"b","text":"定期的に復元を試し、データ整合性と復旧時間を確認する"},{"id":"c","text":"バックアップを本番データと同じ場所だけに保存する"},{"id":"d","text":"復旧手順を文書化しない"}]','"b"','正解は B。バックアップが作成できても復元できるとは限らない。定期的な復元テストで整合性とRTO/RPOへの適合を確認する。','generated','知学 SG 自编练习 v3','ja');

INSERT OR IGNORE INTO practical_scenarios
(id,track_id,title,category,difficulty,situation,task,options_json,best_option,scoring_json,explanation,source_type)
VALUES
('sg-scenario-change-003','exam-sg','紧急修补生产漏洞','脆弱性管理','intermediate','公开服务发现正在被利用的高危漏洞，但修补可能影响生产系统。','最恰当的处置是什么？','[{"id":"a","text":"完全忽略漏洞，等下个月例行更新"},{"id":"b","text":"不做评估直接在生产环境执行所有命令"},{"id":"c","text":"评估暴露和业务影响，启动紧急变更流程，验证修补并准备回滚与监控"},{"id":"d","text":"公开所有服务器地址让外部人员测试"}]','c','{"a":0,"b":20,"c":100,"d":0}','高危漏洞需要快速响应，但仍要评估风险、验证变更、保留记录并准备回滚。紧急流程的目的是加速受控处置，而不是跳过控制。','authored'),
('sg-scenario-log-integrity-001','exam-sg','发现审计日志可被普通员工删除','日志与审计','standard','审计发现普通业务账号拥有删除安全日志的权限，且日志和应用运行在同一台服务器。','优先改进措施是什么？','[{"id":"a","text":"保留现状，只提醒员工不要删除"},{"id":"b","text":"限制日志管理权限，将日志转存到受控的独立位置并监测异常操作"},{"id":"c","text":"删除所有旧日志避免风险"},{"id":"d","text":"让所有员工共同维护管理员密码"}]','b','{"a":0,"b":100,"c":0,"d":0}','日志应限制访问和删除权限，并考虑独立存储、时间同步、完整性保护与异常监控，以提高调查和追责能力。','authored'),
('sg-scenario-sql-injection-001','exam-sg','上线前发现 SQL 注入','应用程序安全','intermediate','上线测试发现搜索参数可以改变 SQL 查询逻辑，开发者建议只在前端过滤特殊字符。','应如何处理？','[{"id":"a","text":"只在前端添加黑名单过滤后立即上线"},{"id":"b","text":"使用参数化查询，在服务端验证输入并补充安全测试后再发布"},{"id":"c","text":"关闭错误日志以隐藏问题"},{"id":"d","text":"给应用数据库账号授予所有管理权限"}]','b','{"a":0,"b":100,"c":0,"d":0}','参数化查询将输入数据与SQL结构分离，服务端验证和安全测试可进一步降低风险。前端校验不能作为安全边界。','authored'),
('sg-scenario-access-revocation-002','exam-sg','员工调岗后的权限复核','访问控制','standard','员工从财务岗位转到普通业务岗位，原有财务系统权限仍未撤销。','最合适的措施是什么？','[{"id":"a","text":"保留所有旧权限以免影响工作"},{"id":"b","text":"共享同事账号继续工作"},{"id":"c","text":"依据新职责重新评估权限，撤销不再需要的授权并记录复核"},{"id":"d","text":"等年度审计时再处理"}]','c','{"a":0,"b":0,"c":100,"d":10}','权限应随岗位职责变化及时调整，遵循最小权限原则，并保留审批和复核记录。','authored'),
('sg-scenario-backup-ransomware-001','exam-sg','勒索软件影响生产文件','事件响应与业务连续性','intermediate','共享文件服务器疑似遭勒索软件加密，用户报告文件扩展名大量变化。','第一阶段应采取什么行动？','[{"id":"a","text":"把可疑文件复制到其他共享目录"},{"id":"b","text":"按事件响应流程隔离受影响系统、报告事件并保全日志和证据"},{"id":"c","text":"立即删除所有备份"},{"id":"d","text":"在未确认安全前从同一网络恢复备份"}]','b','{"a":0,"b":100,"c":0,"d":0}','先控制影响扩散并保全证据。恢复前要确认入侵路径已处理、备份干净且恢复方案经过验证，避免再次感染。','authored'),
('sg-scenario-vendor-data-001','exam-sg','供应商请求完整客户数据','供应链与个人信息','standard','供应商排查故障时要求把完整客户数据库发到个人邮箱，合同没有约定此类数据共享。','应如何回应？','[{"id":"a","text":"直接发送以缩短排障时间"},{"id":"b","text":"拒绝未经授权的传输，走审批流程并评估是否能使用最少化或脱敏数据"},{"id":"c","text":"把数据库密码通过聊天软件发过去"},{"id":"d","text":"先发送后补合同"}]','b','{"a":0,"b":100,"c":0,"d":0}','第三方数据共享必须有合法目的、授权和安全传输安排。优先最小化数据，必要时脱敏，并通过组织批准的渠道处理。','authored');

INSERT OR IGNORE INTO language_cards
(id,language,category,term,reading,meaning_zh,explanation,example,example_meaning_zh,source_type)
VALUES
('ja-work-004','ja','职场与商务语言','差し支えなければ','さしつかえなければ','如果方便的话／如果不介意的话','用于较委婉地请求信息或协助；比直接命令更柔和。','差し支えなければ、資料を共有していただけますか。','如果方便的话，可以共享一下资料吗？','authored'),
('ja-work-005','ja','职场与商务语言','認識に相違がないか確認したいです','にんしきにそういがないかかくにんしたいです','我想确认一下双方理解是否一致','适合确认需求、规格或会议结论，避免误解。','実装範囲について、認識に相違がないか確認したいです。','我想确认一下双方对实现范围的理解是否一致。','authored'),
('ja-work-006','ja','职场与商务语言','対応方針を検討します','たいおうほうしんをけんとうします','我会研究处理方针','表示需要评估方案，不代表已经承诺立即实施。','影響範囲を確認し、対応方針を検討します。','我会确认影响范围并研究处理方针。','authored'),
('ja-work-007','ja','职场与商务语言','念のため共有します','ねんのためきょうゆうします','以防万一，先同步一下','用于补充共享背景信息或风险提醒。','念のため、変更内容を共有します。','以防万一，我先同步一下变更内容。','authored'),
('ja-daily-004','ja','日常与情景会话','少し考えさせてください','すこしかんがえさせてください','请让我稍微考虑一下','在需要时间判断或决定时使用，礼貌而自然。','すぐには決められないので、少し考えさせてください。','我暂时无法马上决定，请让我考虑一下。','authored'),
('ja-grammar-003','ja','词汇与语法','〜ようにしています','〜ようにしています','尽量坚持做……／有意识地做……','表示为了达成某个目标，平时有意识地持续采取某种行动。','毎日、日本語の記事を読むようにしています。','我尽量每天阅读日语文章。','authored'),
('en-work-003','en','职场与商务语言','Could you walk me through it?','','可以带我一步步说明一下吗？','用于请求对方按步骤解释流程或技术内容，语气自然。','Could you walk me through the deployment process?','可以带我一步步说明一下部署流程吗？','authored'),
('en-work-004','en','职场与商务语言','I will look into it.','','我会调查／确认一下','表示会进一步查明情况；不等于承诺马上解决。','I will look into the issue and get back to you.','我会调查这个问题，再回复你。','authored'),
('en-work-005','en','职场与商务语言','Let me make sure I understand.','','让我确认一下我是否理解正确','适合会议中复述需求或确认对方意思。','Let me make sure I understand the requirement correctly.','让我确认一下我是否正确理解了需求。','authored'),
('en-work-006','en','职场与商务语言','There may be a delay.','','可能会有延迟','用于提前说明进度风险，避免给出不确定的保证。','There may be a delay because we are still testing the fix.','由于我们还在测试修复方案，进度可能会延迟。','authored'),
('en-daily-003','en','日常与情景会话','Could you say that again?','','你可以再说一遍吗？','礼貌地请求重复内容，适合日常交流和工作会议。','Sorry, could you say that again a little more slowly?','不好意思，可以再慢一点说一遍吗？','authored'),
('en-grammar-002','en','词汇与语法','be supposed to','','应该／按规定需要','常用于表达规则、预期或安排，不一定是个人意愿。','We are supposed to review the changes before release.','按规定，我们应该在发布前检查变更。','authored');
